<template>
<section class="clock-corrections" v-loading="loading">
  <header><strong>{{admin?'公司补卡与跨日记录':'我的补卡与跨日记录'}}</strong><el-button @click="load">刷新记录</el-button></header>
  <p>补卡须填写实际时间及原因，可附证据截图；通知行政部后，由任一行政人员确认才生效。申请、确认、修改前后及撤回均留记录。跨日/跨组签退另行记录后续上班基准，仍保留15分钟宽限。</p>
  <div v-if="!admin&&showActions" class="correction-actions"><el-button :disabled="!desktop" @click="open('in')">补上班打卡</el-button><el-button :disabled="!desktop" @click="open('out')">补下班打卡</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-table :data="data.items||[]" border><el-table-column v-if="admin" prop="name" label="人员" min-width="110" /><el-table-column prop="day" label="考勤日期" width="120" /><el-table-column label="类型" width="100"><template #default="{row}">{{row.kind==='in'?'补上班':'补下班'}}</template></el-table-column><el-table-column label="申请打卡时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.requested_at)}}</template></el-table-column><el-table-column prop="reason" label="原因" min-width="160" show-overflow-tooltip /><el-table-column label="状态" width="110"><template #default="{row}">{{status(row.status)}}</template></el-table-column><el-table-column label="全程记录" fixed="right" width="110"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">查看记录</el-button></template><div class="correction-detail"><h4>{{row.name}} · 补卡全程记录</h4><el-descriptions :column="2" border size="small"><el-descriptions-item label="考勤日期">{{row.day}}</el-descriptions-item><el-descriptions-item label="申请时间">{{formatBusinessDateTime(row.requested_at)}}</el-descriptions-item><el-descriptions-item label="原因" :span="2">{{row.reason}}</el-descriptions-item><el-descriptions-item label="证据" :span="2"><ScreenshotText :text="row.evidence||'未提供（非必填）'" /></el-descriptions-item></el-descriptions><article v-for="(event,index) in row.history" :key="index"><strong>{{event.action==='submitted'?'提交申请':event.action==='confirmed'?'行政确认':'撤回申请'}}</strong> · {{event.actor_name}} · {{formatBusinessDateTime(event.at)}}<template v-if="event.before||event.after"><p>修改前：上班 {{formatBusinessDateTime(event.before?.check_in)}}；下班 {{formatBusinessDateTime(event.before?.check_out)}}</p><p>修改后：上班 {{formatBusinessDateTime(event.after?.check_in)}}；下班 {{formatBusinessDateTime(event.after?.check_out)}}</p></template></article></div></el-popover></template></el-table-column><el-table-column label="操作" fixed="right" width="110"><template #default="{row}"><el-button v-if="admin&&row.status==='pending'" type="primary" link :disabled="busy||!desktop" @click="confirm(row)">确认补卡</el-button><el-button v-if="!admin&&row.status==='pending'" link :disabled="busy||!desktop" @click="cancel(row)">撤回申请</el-button></template></el-table-column></el-table>
  <h4>跨日/跨组签退及后续上班基准</h4><el-table :data="data.adjustments||[]" border><el-table-column v-if="admin" prop="name" label="人员" min-width="150" /><el-table-column label="原上班时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.check_in)}}</template></el-table-column><el-table-column label="实际签退时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.check_out)}}</template></el-table-column><el-table-column prop="day" label="后续考勤日期" width="135" /><el-table-column label="后续上班时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.next_start)}}</template></el-table-column><el-table-column prop="reason" label="说明" min-width="200" show-overflow-tooltip /><el-table-column label="全程记录" fixed="right" width="110"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link>查看记录</el-button></template><div class="correction-detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="原上班时间">{{formatBusinessDateTime(row.check_in)}}</el-descriptions-item><el-descriptions-item label="实际签退">{{formatBusinessDateTime(row.check_out)}}</el-descriptions-item><el-descriptions-item label="后续上班基准">{{formatBusinessDateTime(row.next_start)}}</el-descriptions-item><el-descriptions-item label="说明">{{row.reason}}</el-descriptions-item></el-descriptions><article v-for="(entry,index) in row.history||[]" :key="index"><p>记录：{{formatBusinessDateTime(entry.at)}}；原因：{{entry.reason}}</p><p>原上班：{{formatBusinessDateTime(entry.source_check_in)}}；签退：{{formatBusinessDateTime(entry.source_check_out)}}；后续上班：{{formatBusinessDateTime(entry.next_start)}}</p><p v-for="change in entry.updated_records||[]" :key="change.record_id">后续打卡 {{change.record_id}}：原基准 {{formatBusinessDateTime(change.before?.shift?.late_start_at)}} → {{formatBusinessDateTime(change.after?.shift?.late_start_at)}}</p></article></div></el-popover></template></el-table-column><el-table-column label="记录时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.created_at)}}</template></el-table-column></el-table>
  <DraggableFormDialog v-model="visible" :title="form.kind==='in'?'补上班打卡':'补下班打卡'" append-to-body width="min(800px, calc(100vw - 32px))" top="5vh" class="clock-correction-dialog" :close-on-click-modal="false" :before-close="close">
    <template #header><DialogFieldSearchHeader ref="fieldSearchRef" v-model="fieldSearchKeyword" :title="form.kind==='in'?'补上班打卡':'补下班打卡'" :fetch-suggestions="fetchFieldSuggestions" @select="locateDialogField" @clear="clearFieldSearch" /></template>
    <div ref="body"><AppForm ref="formRef" :model="form" :rules="rules" label-position="top">
      <el-form-item label="考勤日期（原上班日期）" prop="day"><el-date-picker v-model="form.day" type="date" value-format="YYYY-MM-DD" /></el-form-item>
      <el-form-item :label="form.kind==='out'?'选择原上班记录':'已有记录（需要修正时选择，可不选）'" prop="record_id"><el-select v-model="form.record_id" clearable filterable @change="chooseRecord"><el-option v-for="row in data.clock_records||[]" :key="row.id" :value="row.id" :label="`${row.day} · ${row.shift?.label||'班次'} · 第${row.segment+1}组 · ${formatBusinessDateTime(row.check_in)}`" /></el-select></el-form-item>
      <el-form-item v-if="form.kind==='in'&&!form.record_id" label="第几组上下班打卡"><el-input-number v-model="displayGroup" :min="1" :precision="0" /></el-form-item>
      <el-form-item :label="form.kind==='in'?'实际应补上班时间':'实际应补下班时间'" prop="requested_at"><el-date-picker v-model="form.requested_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY年MM月DD日 HH:mm:ss" /></el-form-item>
      <el-form-item v-if="form.kind==='out'" label="下次/第二天上班时间（顺延时间）" prop="next_start"><el-date-picker v-model="form.next_start" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY年MM月DD日 HH:mm:ss" /></el-form-item>
      <el-form-item label="向行政部说明原因" prop="reason"><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="2000" /></el-form-item>
      <el-form-item label="证据截图及说明（非必填）"><ScreenshotInput v-model="form.evidence" type="textarea" :rows="3" maxlength="16000" placeholder="可粘贴或插入证据截图" /></el-form-item>
      <el-form-item label="提前到达的时间是否确实已在工作" prop="early_work_confirmed"><el-radio-group v-model="form.early_work_confirmed"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></el-form-item>
      <el-form-item label="是否在早餐后打卡" prop="breakfast_after_eating"><el-radio-group v-model="form.breakfast_after_eating"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></el-form-item>
      <el-form-item v-if="form.kind==='out'&&askDinner" label="是否进食晚餐" prop="dinner_eaten"><el-radio-group v-model="form.dinner_eaten"><el-radio :value="true">有</el-radio><el-radio :value="false">无</el-radio></el-radio-group></el-form-item>
      <template v-if="form.kind==='out'&&atHome"><p>郑重提示：请确认打卡期间均为真实有效工作时间。弄虚作假一经查实，公司有权视情节每次处以50—200元绩效扣款，并给予警告或通报批评等纪律处分。</p><el-form-item label="是否扣除无效时间" prop="deduct_invalid_time"><el-radio-group v-model="form.deduct_invalid_time"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></el-form-item><template v-if="form.deduct_invalid_time"><el-form-item label="无效分钟数" prop="invalid_minutes"><el-input-number v-model="form.invalid_minutes" :min="0.01" :max="1440" /></el-form-item><el-form-item label="无效时间说明" prop="invalid_reason"><el-input v-model="form.invalid_reason" type="textarea" /></el-form-item></template></template>
    </AppForm><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /></div>
    <template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submit">提交并通知行政部</el-button></template>
  </DraggableFormDialog>
</section>
</template>
<script setup>
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import DraggableFormDialog from '@/components/common/DraggableFormDialog.vue'
import DialogFieldSearchHeader from '@/components/common/DialogFieldSearchHeader.vue'
import ScreenshotInput from '@/components/common/ScreenshotInput.vue'
import ScreenshotText from '@/components/common/ScreenshotText.vue'
import {useDialogFieldSearch} from '@/composables/useDialogFieldSearch'
import {getClockCorrections,requestClockCorrection,confirmClockCorrection,cancelClockCorrection} from '@/api/attendance'
import {businessDateTimeInputValue,formatBusinessDateTime} from '@/utils/dateTime'
import {subscribe} from '@/utils/realtimeSocket'
import {chatClientType} from '@/utils/chatDevice'
const props=defineProps({admin:Boolean,showActions:{type:Boolean,default:true}}),emit=defineEmits(['changed']),desktop=chatClientType(navigator)==='desktop'
const data=ref({}),loading=ref(false),error=ref(''),visible=ref(false),busy=ref(false),saveError=ref(''),body=ref(),formRef=ref()
const empty=()=>({id:'clock-correction-new',client_id:'',day:businessDateTimeInputValue(new Date()).slice(0,10),kind:'in',segment:0,record_id:null,requested_at:null,next_start:null,reason:'',evidence:'',early_work_confirmed:null,breakfast_after_eating:null,dinner_eaten:null,deduct_invalid_time:null,invalid_minutes:0,invalid_reason:''})
const form=reactive(empty()),displayGroup=computed({get:()=>form.segment>=3?form.segment:form.segment+1,set:value=>{form.segment=Number.isInteger(value)&&value>0?(value>=3?value:value-1):0}}),selected=computed(()=>data.value.clock_records?.find(row=>row.id===form.record_id)),atHome=computed(()=>selected.value?.shift?.home_office_day||selected.value?.shift?.home_rotation||selected.value?.shift?.code==='customer_remote'),askDinner=computed(()=>!selected.value?.shift?.home_rotation&&selected.value?.shift?.code!=='customer_remote'&&['late','late_late'].includes(selected.value?.shift?.code))
const choice={validator:(_r,v,done)=>done(typeof v==='boolean'?undefined:new Error('请选择是或否')),trigger:'change'}
const rules=computed(()=>({day:[{required:true,message:'请选择考勤日期'}],record_id:form.kind==='out'?[{required:true,message:'请选择原上班记录'}]:[],requested_at:[{required:true,message:'请填写实际打卡时间'}],next_start:form.kind==='out'?[{required:true,message:'请填写下次或第二天上班时间'}]:[],reason:[{required:true,whitespace:true,message:'请说明原因'}],early_work_confirmed:[choice],breakfast_after_eating:[choice],dinner_eaten:form.kind==='out'&&askDinner.value?[choice]:[],deduct_invalid_time:form.kind==='out'&&atHome.value?[choice]:[],invalid_minutes:form.deduct_invalid_time?[{required:true,type:'number',min:0.01,message:'请填写大于0的无效分钟数'}]:[],invalid_reason:form.deduct_invalid_time?[{required:true,whitespace:true,message:'请填写无效时间说明'}]:[]}))
const {fieldSearchRef,fieldSearchKeyword,fetchFieldSuggestions,locateDialogField,clearFieldSearch}=useDialogFieldSearch(body)
watch(()=>form.deduct_invalid_time,value=>{if(value!==true){form.invalid_minutes=0;form.invalid_reason=''}})
const status=value=>({pending:'待行政确认',confirmed:'已确认',cancelled:'已撤回'})[value]||value
let alive=true,controller,sequence=0,unsubscribe
async function load(){controller?.abort();controller=new AbortController();const seq=++sequence;loading.value=true;error.value='';try{const value=await getClockCorrections(props.admin,{signal:controller.signal});if(alive&&seq===sequence)data.value=value}catch(e){if(alive&&seq===sequence&&e.code!=='ERR_CANCELED')error.value=e.detail||'读取补卡记录失败'}finally{if(alive&&seq===sequence)loading.value=false}}
function open(kind){Object.assign(form,empty(),{kind,client_id:crypto.randomUUID()});saveError.value='';clearFieldSearch();visible.value=true;nextTick(()=>formRef.value?.clearValidate())}
defineExpose({open})
function chooseRecord(){if(selected.value)form.day=selected.value.day;form.dinner_eaten=null;form.deduct_invalid_time=null;form.invalid_minutes=0;form.invalid_reason=''}
function close(done){if(!busy.value)done()}
async function submit(){if(busy.value||!await formRef.value.validate().catch(()=>false))return;busy.value=true;saveError.value='';try{const {id,...payload}=form;await requestClockCorrection({...payload,requested_at:`${form.requested_at}+08:00`,next_start:form.next_start?`${form.next_start}+08:00`:null});visible.value=false;ElMessage.success('申请已通知行政部，确认后生效');load()}catch(e){saveError.value=typeof e.detail==='string'?e.detail:'补卡申请未提交成功'}finally{busy.value=false}}
async function confirm(row){await ElMessageBox.confirm(`确认${row.name}的${row.kind==='in'?'上班':'下班'}补卡时间为${formatBusinessDateTime(row.requested_at)}？确认后会更新考勤并留记录。`,'确认补卡',{confirmButtonText:'确认补卡',cancelButtonText:'取消',type:'warning'}).then(async()=>{busy.value=true;try{await confirmClockCorrection(row.id);ElMessage.success('补卡已确认');load();emit('changed');window.dispatchEvent(new Event('attendance-clock-changed'))}catch(e){ElMessage.error(e.detail||'确认失败')}finally{busy.value=false}}).catch(()=>{})}
async function cancel(row){busy.value=true;try{await cancelClockCorrection(row.id);load()}catch(e){ElMessage.error(e.detail||'撤回失败')}finally{busy.value=false}}
onMounted(()=>{load();unsubscribe=subscribe('attendance_clock_changed',load)});onBeforeUnmount(()=>{unsubscribe?.();alive=false;sequence++;controller?.abort()})
</script>
<style scoped>.clock-corrections{font-size:13px;line-height:1.8;min-width:0}.clock-corrections header,.correction-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.clock-corrections header{justify-content:space-between}.clock-corrections p{color:#64748b}.correction-detail{max-height:560px;overflow-y:auto;overflow-wrap:anywhere}.correction-detail article{border-top:1px solid #e2e8f0;padding:10px 0}</style>
<style>.clock-correction-dialog.el-dialog{display:flex;flex-direction:column;max-height:90vh;overflow:hidden}.clock-correction-dialog>.el-dialog__header,.clock-correction-dialog>.el-dialog__footer{flex-shrink:0}.clock-correction-dialog>.el-dialog__body{flex:1;min-height:0;overflow-y:auto}.clock-correction-dialog>.el-dialog__footer{border-top:1px solid #e2e8f0;background:#f8fafc}</style>
